import{_ as s,o as n,c as r,a3 as l}from"./chunks/framework.z_KJ15Ep.js";const g=JSON.parse('{"title":"Abschlüsse am Berufskolleg berechnen","description":"","frontmatter":{"title":"Abschlüsse am Berufskolleg berechnen","source_pageid":1292,"source_revision":4732},"headers":[],"relativePath":"zeugnisse/berufskolleg/abschluss-berechnen-gruppenprozesse-bk-abschluss.md","filePath":"zeugnisse/berufskolleg/abschluss-berechnen-gruppenprozesse-bk-abschluss.md"}'),h={name:"zeugnisse/berufskolleg/abschluss-berechnen-gruppenprozesse-bk-abschluss.md"};function a(c,e,u,t,i,o){return n(),r("div",null,[...e[0]||(e[0]=[l(`<h1 id="abschlusse-am-berufskolleg-berechnen" tabindex="-1">Abschlüsse am Berufskolleg berechnen <a class="header-anchor" href="#abschlusse-am-berufskolleg-berechnen" aria-label="Permalink to &quot;Abschlüsse am Berufskolleg berechnen&quot;">​</a></h1><p>Berechnen Sie die für den ausgewählten Bildungsgang vorgesehenen schulischen und beruflichen Abschlüsse sowie gegebenenfalls die Fachhochschulreife.</p><p>Basierend auf den Prüfungsordnungen beziehungsweise Bildungsgängen und Jahrgängen kann über den Gruppenprozess <strong>Abschluss berechen</strong> die Prüfung auf schulische und berufliche Abschlüsse angestoßen werden.</p><p>Ebenso werden eventuelle FHR-Abschlüsse und -durchschnitte berechnet.</p><p>Im Reiter <em>Schüler ➜ BK-Abschluss</em> werden unter <em>Abschluss</em> die Felder <strong>AB</strong> und <strong>BA</strong> entsprechend auf <em>Ja</em> oder <em>Nein</em> gesetzt.</p><p>Die Ergebnisse finden sich dann im Reiter <em>Schüler Akt. ➜ Abschnitt</em>.</p><p>Ein Protokolleintrag könnte wie folgt aussehen:</p><pre><code> Datum: 29.01.2024 15:08:14
 Einhorn, Fantayala (AVI1)
 ========================================================================
 Prüfungsordnung: ESA: Erster Schulabschluss nach APO-BK-15, Anl.A
 Nicht ausreichende Leistung in Mathematik, Ausgleichsfach Naturwissenschaften (mit gleichem Stundenumfang)
 Ergebnis:
 Erster Schulabschluss und berufliche Kenntnisse, Fähigkeiten und Fertigkeiten erreicht!   
</code></pre><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Abschluss_berechnen_(Gruppenprozesse_BK-Abschluss)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4732.</p>`,10)])])}const p=s(h,[["render",a]]);export{g as __pageData,p as default};
